const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');const file=process.env.TARGET_FILE,parent=process.env.PARENT_SHA,parentBlob=process.env.PARENT_BLOB,targetBlob=process.env.TARGET_BLOB,hash=process.env.TARGET_HASH,bytes=Number(process.env.TARGET_BYTES);const ok=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();ok(sh(`git rev-parse ${parent}:${file}`)===parentBlob,'parent blob drift');const src=cp.execSync(`git show ${parent}:${file}`,{encoding:'utf8'}),had=src.endsWith('\n'),lines=src.replace(/\n$/,'').split('\n');for(const n of [240,239,129,127,78,77,76,75]){ok(lines[n-1]!==undefined,`missing ${n}`);lines.splice(n-1,1);}const rebuilt=Buffer.from(lines.join('\n')+(had?'\n':'')),current=fs.readFileSync(file);ok(Buffer.compare(rebuilt,current)===0,'byte identity drift');ok(sh(`git hash-object ${file}`)===targetBlob,'target blob drift');const actual=crypto.createHash('sha256').update(current).digest('hex');ok(actual===hash,'hash drift');ok(current.length===bytes,'bytes drift');console.log(`EXACT BYTE IDENTITY PASS|parent=${parent}|parentBlob=${parentBlob}|targetBlob=${targetBlob}|hash=${actual}|bytes=${current.length}|decl=303->295|dead=8->0|staticCascadeRows=8|identicalWinners=1|changedWinners=7`);
